from urllib.parse import quote
R=Path(__file__).resolve().parents[1]
SFR='https://sfr.gov.ru/employers/lk_insurer/baza_znanij/teh_voprosy/'
RT='https://rtmis.ru/assets/files/rekomendacii-po-formirovaniyu-ln-s-ispolzovaniem-ecp.mis-v1-5.pdf'
RT3='https://rtmis.ru/'+quote('Руководство пользователя ЕЦП.МИС. 3.0_Подсистема Документ о временной нетрудоспособности. Реестры ЛВН.pdf')
REM='https://rtmis.ru/'+quote('РП. ЕЦП. МИС. 3.0. Взаимодействие с ЕГИСЗ. РЭМД 3.0.6.v1.pdf')
SPB='https://spbmiac.ru/wp-content/uploads/2022/06/'+quote('Обучение-ошибки-РЭМД-v.7-2.pdf')
MR='https://kb.1cmr.ru/pages/viewpage.action?pageId='
rows=[]
def add(title,code,cause,steps,urls,markers,*,aliases=(),text=None,category='Больничные листы и ЭЛН',workflow='Отправка или получение электронного листка нетрудоспособности',product='Сервис ЭЛН СФР; применимость к обмену вашей 1С требует проверки',version='Версия МИС неизвестна',date='Дата публикации не установлена',locator='',possible=False,solved=False,note=''):
    codes=[code,*aliases] if code else []
    rows.append(dict(id=f'{160+len(rows):03}',title=title,category=category,original_error_text=text,error_code=code,error_codes=codes,rule_codes=[],status_codes=[],error_namespace='ЭЛН СФР' if category.startswith('Больничные') else 'РЭМД',alternative_search_phrases=list(dict.fromkeys([*codes,*markers,title])),keywords=re.findall(r'[\w-]+',title.lower())+(['больничный','ЭЛН','СФР','ФСС'] if category.startswith('Больничные') else ['РЭМД','СЭМД']),workflow=workflow,cause=cause,cause_confidence='Возможная причина' if possible else 'Расшифровка или условие подтверждены источником',physician_instructions=steps,escalation_instructions=('Ответственный за ЭЛН и местная поддержка МИС' if category.startswith('Больничные') else 'Местная поддержка МИС и ответственный за обмен с РЭМД')+': передайте код, слова сообщения, операцию, время сбоя и статус документа без данных пациента.',source_urls=urls,evidence_status=['Возможно' if possible and not solved else 'Подтверждено','Требует локальной проверки'],software_product=product,software_version=version,local_verification_status='В целевой больнице Иванова не проверено',source_date=date,checked_on='2026-10-30',evidence_note=note or 'Подтверждено значение сообщения, а не успешное исправление в целевой больнице. Действия врача — безопасная редакционная адаптация; техническое исправление выполняет поддержка.',source_locator=locator,confirmed_solution=solved,clarifying_questions=['В какой системе и при какой операции появился код?','Какие слова идут после кода? Не передавайте данные пациента.','Каков текущий статус документа?'],safety_note='Не создавайте дубликат, не аннулируйте и не отправляйте документ повторно без проверки его состояния и согласования местного порядка.',diagnostic_markers=markers,context_required=True))

add('ЭЛН уже изменён: открыта устаревшая запись','ORA-20013','Возможная причина: другой пользователь уже изменил этот ЭЛН. Открытая у вас версия больше не актуальна.', ['Уточните актуальное состояние ЭЛН через предусмотренное в вашей МИС получение сведений; при необходимости попросите ответственного за ЭЛН.','Сверьте принятые сведения со своими правками. Продолжайте только фактически необходимую операцию, согласовав расхождения.'],[SFR,RT3],['потеряла актуальность','обновить данные','другой пользователь'],aliases=['-20013'],text='Не удалось обновить данные. Обновляемая запись потеряла актуальность',possible=True,solved=True,locator='СФР: вопрос ORA-20013; ЕЦП.МИС 3.0: раздел 4.5, таблица ответов ФСС')
add('Сервис не определил этап оформления ЭЛН','ORA-20015','Возможная причина: уже приняты те же сведения либо отправленные данные не соответствуют этапу оформления ЭЛН.', ['Проверьте актуальные сведения и статус ЭЛН в СФР через вашу МИС или ответственного сотрудника.','Сверьте отправляемую операцию с уже принятой. Не добавляйте новый период только для обхода ошибки; спорные изменения согласуйте с ответственным за ЭЛН.'],[SFR,RT3],['определить состояние ЭЛН','данные уже присутствуют','дублирование данных','Направленные данные ЭЛН уже присутствуют в системе'],aliases=['-20015'],text='Не удалось определить состояние ЭЛН',possible=True,solved=True,locator='СФР: вопрос ORA-20015; ЕЦП.МИС 3.0: раздел 4.5, вариант сообщения о повторных данных')
add('Доступ к ЭЛН ограничен его текущим статусом','ORA-20001','Возможная причина: текущий этап ЭЛН не разрешает запрошенный доступ вашей роли. СФР описывает ограничения отдельно для работодателя и бюро МСЭ.', ['На рабочем месте сверьте выбранный ЭЛН и операцию: получение, продление, закрытие или направление на МСЭ.','Передайте ответственному за ЭЛН текущий статус для проверки маршрута и роли. Не меняйте статус ради доступа: требование закрыть листок для работодателя не является общим правилом для врача.'],[SFR],['доступ к ЭЛН','ограничен','статус'],possible=True,locator='СФР: вопрос ORA-20001; примеры работодателя и бюро МСЭ')
add('В ЭЛН по уходу расходятся даты окончания периодов','ELR_1703','Проверка обнаружила несовпадение окончания очередного периода ухода и периода освобождения от работы.', ['Получите актуальные сведения ЭЛН штатным способом вашей МИС или через ответственного за ЭЛН.','Сверьте фактические периоды в двух блоках. Коррекцию согласуйте по местному порядку; не подгоняйте даты и не оформляйте дубликат самостоятельно.'],[SFR],['окончание очередного периода','по уходу','освобождение от работы'],solved=True,locator='СФР: вопрос ELR_1703',note='СФР описывает запрос актуальных сведений и коррекцию периодов. Аннулирование и дубликат не перенесены в самостоятельные действия врача.')

rtmeta=dict(product='Внешний сервис ЭЛН; код приведён в документации ЕЦП.МИС, а не конфигурации 1С',version='ЕЦП.МИС: рекомендации 2022 года и руководство 3.0; релиз 1С неизвестен',date='2022; дата руководства 3.0 не установлена',locator='Рекомендации 2022: приложение 2, с. 105; руководство ЕЦП.МИС 3.0: раздел 4.5',note='Сверена колонка кода, полученного в ответе сервиса. Внутренние номера строк таблицы не являются кодами 1С. Источник даёт расшифровку без подтверждённого исправления.')
add('Подпись электронного больничного не принята','ERR_SIGN','Сервис сообщает о некорректной электронной подписи. Конкретная причина по этому коду точно не установлена.', ['Уточните, на каком этапе возник отказ: подпись врача, организации или отправка ЭЛН.','Проверьте выбранного подписанта и статус ЭЛН. Передайте поддержке проверку подписи; не удаляйте её и не меняйте настройки защиты.'],[RT,RT3],['некорректная ЭП','подпись ЭЛН'],text='Некорректная ЭП',**rtmeta)
add('Номер основного больничного признан недействительным','ELR_899','При проверке номер основного листка найден среди недействительных номеров.', ['Сверьте на рабочем месте номер и связь с основным листком. Не переносите номер пациента в поиск на телефоне.','Обратитесь к ответственному за ЭЛН, чтобы проверить действующий основной листок и допустимое продолжение. Новый листок для обхода отказа не создавайте.'],[RT,RT3],['основного листка','недействительных номеров'],**rtmeta)
add('В номере больничного не двенадцать цифр','ELR_8','Сервис отклонил формат номера листка: ожидаются 12 цифр.', ['На рабочем месте сверьте номер с исходными сведениями; проверьте пропуск цифры или посторонний знак. Не подбирайте номер.','Если номер правильный, попросите поддержку проверить, какое значение передаётся. Перед повторной отправкой уточните, не принят ли ЭЛН.'],[RT,RT3],['Номер ЛН','12 цифр','двенадцать'],**rtmeta)
add('В ЭЛН отправлено несколько новых периодов сразу','ERR','В этом варианте сообщения сервис отклоняет отправку более одного нового периода за операцию.', ['Убедитесь, что после ERR говорится именно о количестве новых периодов. Для текста об ограничении доступа нужен другой разбор.','Сверьте уже принятые периоды с подготовленными. Попросите ответственного за ЭЛН согласовать порядок передачи; не удаляйте действительные периоды.'],[RT,RT3],['количество новых периодов','не должно превышать 1'],**rtmeta)
add('Сервис отказал в доступе к больничному','ERR','Текст сообщает об ограничении доступа. Причина точно не установлена: таблица источника не уточняет роль и статус ЭЛН.', ['Сверьте слова после ERR: этот разбор относится к доступу к ЭЛН, а не к числу периодов.','Попросите ответственного за ЭЛН проверить статус и разрешённую операцию. Самостоятельно менять права или состояние листка не нужно.'],[RT,RT3],['доступ к ЭЛН ограничен','отказ доступа'],**rtmeta)

mrmeta=dict(product='Линия 1C-MR; региональная реализация на 1С',version='Релиз не указан')
add('Фамилия в ЭЛН отличается от ранее переданной','', 'Возможная причина: ранее ФИО были переданы прописными буквами, а теперь — строчными. Именно такой случай разобран поддержкой 1C-MR.', ['Сверьте фактические ФИО и слова сообщения на рабочем месте. Не изменяйте действительные сведения наугад.','Попросите поддержку сопоставить ранее принятые и текущие сведения. Групповое изменение реквизитов из технической инструкции врач самостоятельно не выполняет.'],[MR+'46008203'],['Фамилия застрахованного','отличается от существующего значения','регистр букв'],text='Значение поля «Фамилия застрахованного» отличается от существующего значения',possible=True,solved=True,date='2022-10-12',locator='Полный текст разбора; техническое исправление передано поддержке',**mrmeta)
rows[-1]['error_code']=None
add('Продолжение ЭЛН не видно в списке','', 'В описанном случае продолжение связано не с тем основным ЭЛН либо связь отсутствует. Поддержка связывает это с непоследовательным получением листков.', ['Уточните у ответственного за ЭЛН, существует ли нужное продолжение и к какому основному листку оно относится.','Попросите поддержку проверить связь документов. Не создавайте повторное продолжение и не изменяйте технические реквизиты самостоятельно.'],[MR+'96502064'],['не видно продолжение','первичный ЭЛН','список больничных'],solved=True,date='2024-02-01',locator='Полный текст разделов «Проблема» и «Решение»',**mrmeta)
rows[-1]['error_code']=None
remmeta=dict(category='Отправка электронных документов',workflow='Регистрация СЭМД в федеральном РЭМД',product='РЭМД; разбор в руководстве ЕЦП.МИС, применимость к вашей 1С требует проверки',version='ЕЦП.МИС 3.0; документ РЭМД 3.0.6.v1; релиз 1С неизвестен',locator='Раздел автоматической повторной отправки, с. 14–15',note='Перенесено значение внешнего отказа. Настройки и автоматическая переотправка ЕЦП.МИС не приписываются 1С.')
add('РЭМД не распознал систему-отправителя','NO_RMIS','РЭМД не распознал медицинскую систему как зарегистрированный источник документов.', ['Проверьте статус отправки исходного СЭМД и запишите время отказа.','Сообщите поддержке код и название системы. Проверка регистрации отправителя относится к настройкам обмена; изменение текста медицинской записи проблему не устраняет.'],[REM],['источник СЭМД','не зарегистрирована в РЭМД'],**remmeta)
add('Медицинской системе отказано в доступе к РЭМД','ACCESS_DENIED','В описанном контексте регистрации СЭМД медицинская система не имеет доступа к РЭМД. Код в другой операции может означать иное.', ['Убедитесь, что отказ относится к регистрации СЭМД, и уточните статус исходного документа.','Передайте случай местной поддержке: ей нужно проверить доступ системы и при необходимости обратиться в поддержку ЕГИСЗ. Не запрашивайте расширение личных прав врача только по этому коду.'],[REM],['нет доступа к РЭМД','регистрация СЭМД'],**remmeta)
add('Организация подписанта не совпала с отправителем','SIGNER_ORG_MISMATCH','Возможная причина: организация подписанта отличается от организации, регистрирующей документ.', ['Сверьте организацию, от которой оформлен документ, и выбранного подписанта.','Попросите поддержку проверить соответствие организации и подписи. Не выбирайте чужую подпись и не переподписывайте документ до согласования.'],[SPB],['организация подписанта','регистрирующей документ'],category='Подписание документов',workflow='Отказ РЭМД при регистрации подписанного СЭМД',product='РЭМД; учебный материал СПб МИАЦ',possible=True,locator='Только индексированный фрагмент страницы 5; весь PDF недоступен',note='Поисковый индекс первичного материала содержит код и его расшифровку. Полный PDF не прочитан: ошибка загрузки и предупреждение сертификата Safari. Разбор предварительный; подтверждённого исправления нет.')
add('Дата начала освобождения отклонена сервисом ЭЛН','ELR_1607','Возможная причина: указанная дата начала освобождения позже завтрашнего дня. Такое сообщение видно в индексированном примере руководства СФР.', ['Сверьте фактическую дату на рабочем месте. Не меняйте её на допустимую только ради отправки.','Если дата соответствует документам, передайте случай ответственному за ЭЛН: нужно проверить допустимость оформления и версию обмена.'],['https://lk.sfr.gov.ru/eln/User_instruct.pdf'],['дата освобождения','с какого числа','позже завтрашнего дня'],possible=True,version='На индексированном примере АРМ 2.01.25.2024110201; версия вашей МИС неизвестна',locator='Только индексированный текст рисунка 45 перед разделом 4.5.3',note='Полный PDF загрузить не удалось. Установлена связь кода и текста в индексированном примере, но актуальное правило и исправление требуют проверки. Другие коды из таблицы без расшифровок не добавлены.')
(R/'research/codes-v5/cards.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
print(f'Добавлено {len(rows)} карточек: {rows[0]["id"]}–{rows[-1]["id"]}')
